def count_boundary_maximum_subarrays(nums):
    stack=[];answer=0
    for value in nums:
        while stack and stack[-1][0]<value:stack.pop()
        if not stack or stack[-1][0]>value:stack.append([value,1])
        else:stack[-1][1]+=1
        answer+=stack[-1][1]
    return answer

